  "Remove this passkey?": "Hapus kunci sandi ini?",
  "Scan this with the other device, or open openGym there and enter the code on the sign-in screen. It works once, for {0} minutes.": "Pindai ini dengan perangkat lain, atau buka openGym di perangkat tersebut dan masukkan kode di layar masuk. Berlaku sekali pakai selama {0} menit.",
  "That code is wrong, already used or expired. Make a new one on your other device.": "Kode itu salah, sudah digunakan atau kedaluwarsa. Buat yang baru di perangkatmu yang lain.",
  "This browser cannot confirm with your passkey. Do this on a device that holds one.": "Browser ini tidak dapat mengonfirmasi dengan kunci sandimu. Lakukan ini pada perangkat yang memilikinya.",
  "First confirm that it is you.": "Konfirmasikan terlebih dahulu bahwa itu memang kamu.",
  "This profile has no passkey, and this server does not take passwords, so nothing here can confirm that it is you. Ask your admin.": "Profil ini tidak memiliki kunci sandi, dan server ini tidak menerima kata sandi, jadi tidak ada apa pun di sini yang dapat mengonfirmasi bahwa itu memang kamu. Tanyakan pada adminmu.",
  "This browser cannot create passkeys, so it cannot be added with a code. Open the link in a browser that can.": "Browser ini tidak dapat membuat kunci sandi, sehingga tidak dapat ditambahkan kode. Buka link tersebut di browser yang bisa.",
  "This browser is signed in as “{0}”. Adding it to “{1}” signs “{0}” out here.": "Browser ini terhubung sebagai “{0}”. Menambahkannya ke “{1}” akan mengeluarkan “{0}” dari browser ini.",
  "This code is for a different profile that is also called “{0}”, not the one this browser is signed in as. Adding it there signs yours out here.": "Kode ini untuk profil lain yang juga bernama “{0}”, bukan yang sedang terhubung di browser ini. Menambahkannya di sana akan mengeluarkan akunmu dari browser ini.",
  "Only continue if this code comes from a device of your own. This browser is then signed in to “{0}”, and what you log here goes to that profile.": "Lanjutkan hanya jika kode ini berasal dari perangkatmu sendiri. Browser ini akan masuk ke “{0}”, dan apa yang kamu catat di sini akan tersimpan ke profil tersebut.",
