  "Use a code from your other device": "Gunakan kode dari perangkatmu yang lain",
  "You get a code that lets your phone or another computer create a passkey for this profile. First confirm that it is you.": "Kamu mendapatkan kode yang memungkinkan ponselmu atau komputer lain membuat kunci sandi untuk profil ini. Konfirmasikan terlebih dahulu bahwa itu memang kamu.",
