  "Your plan goes back to how it was before you accepted them. Workouts you have logged since are untouched.": "Rencanamu akan kembali seperti sebelum perubahan tersebut diterapkan. Sesi latihan yang sudah kamu catat setelahnya tidak akan berubah.",
  "Undo": "Urungkan",
