  "{0}h {1}m": "{0}j {1}m",
  "The Coach is on": "Pelatih AI aktif",
  "the configured AI provider": "penyedia AI yang dikonfigurasi",
  "Your name, your sign-in details and everything else about your account stay here. Other people’s data is never included.": "Namamu, detail masuk kamu, dan semua hal lain tentang akunmu tetap di sini. Data orang lain tidak pernah disertakan.",
  "The Coach is not a doctor or a physiotherapist. If something hurts, ask a professional.": "Pelatih bukanlah seorang dokter atau fisioterapis. Jika ada yang sakit, tanyakan pada profesional.",
  "Not now": "Tidak sekarang",
  "Meet the Coach": "Temui Pelatih",
  "Review": "Tinjauan",
  "Automatic reviews": "Ulasan otomatis",
  "Off. The Coach only looks when you ask.": "Nonaktif. Pelatih hanya meninjau saat kamu meminta.",
  "You are only notified when the Coach actually has something to suggest.": "Kamu hanya diberitahu ketika Pelatih benar-benar mempunyai sesuatu untuk disarankan.",
  "On this phone the Coach can only look while the app is open: right after a workout, or the next time you open it.": "Di ponsel ini, Pelatih hanya dapat melihat saat aplikasi terbuka: tepat setelah selesai latihan, atau saat kamu membukanya lagi.",
  "When": "Kapan",
  "Weekly": "Mingguan",
  "On a day and time you choose": "Pada hari dan waktu yang kamu pilih",
  "After every few workouts": "Setelah setiap beberapa latihan",
  "As soon as you have logged enough": "Segera setelah catatan latihanmu cukup",
  "Day": "Hari",
  "After how many workouts": "Setelah berapa banyak latihan",
  "applied": "diterapkan",
  "declined": "ditolak",
  "Your plan": "Rencanamu",
  "What are you training for?": "Untuk apa kamu berlatih?",
  "Where are you starting from?": "Dari mana kamu memulai?",
  "How many days a week?": "Berapa hari dalam seminggu?",
  "Which days suit you? (optional)": "Hari apa yang cocok untukmu? (opsional)",
  "How long is a session?": "Berapa lama satu sesi?",
  "min": "menit",
  "The Coach fits the volume to the time you actually have, including rest between sets.": "Pelatih menyesuaikan volume dengan waktu yang sebenarnya kamu miliki, termasuk istirahat antarset.",
  "What can you train with?": "Dengan apa kamu bisa berlatih?",
  "Pick everything you have access to. Leave it empty and the Coach will use the whole library.": "Pilih semua alat yang kamu miliki. Biarkan kosong jika ingin Pelatih AI menggunakan seluruh katalog latihan.",
  "Anything to work around?": "Ada yang perlu diatasi?",
  "Injuries, joints that complain, movements you cannot do, or practical limits like training at 6am in a flat.": "Cedera, sendi yang sering bermasalah, gerakan yang tidak bisa dilakukan, atau batasan praktis seperti latihan jam 6 pagi di apartemen.",
  "e.g. “dodgy left shoulder, no barbell overhead press”": "mis. “bahu kiri sering bermasalah, hindari barbell overhead press”",
  "If something actually hurts, see a professional. The Coach will program conservatively, but it can’t diagnose anything.": "Jika ada yang benar-benar sakit, temui profesional. Pelatih akan membuat program secara konservatif, namun tidak dapat mendiagnosis apa pun.",
  "Anything else?": "Ada lagi?",
  "Exercises you love": "Latihan yang kamu sukai",
  "e.g. “deadlifts, anything with a kettlebell”": "mis. “deadlift, apa pun yang menggunakan kettlebell”",
  "Exercises you would rather not": "Latihan yang tidak kamu sukai",
  "e.g. “I hate lunges”": "mis. “Aku benci lunge”",
  "Anything you want the Coach to know": "Apa pun yang kamu ingin Pelatih ketahui",
  "e.g. “I want visible arms progress by spring”": "mis. “ingin progres otot lengan terlihat jelas dalam beberapa bulan”",
  "Build my plan": "Bangun rencanaku",
  "Your plan is live": "Rencanamu sudah aktif",
  "That proposal can’t be read.": "Proposal itu tidak dapat dibaca.",
  "Discard this plan?": "Buang rencana ini?",
  "Nothing is saved, and you can ask again anytime.": "Tidak ada yang disimpan, dan kamu dapat bertanya lagi kapan saja.",
  "Revision {0}": "Revisi {0}",
  "Replaces your current week. Days this plan leaves empty become rest days.": "Menggantikan minggumu saat ini. Hari-hari yang dikosongkan oleh rencana ini menjadi hari istirahat.",
  "Could not apply those changes": "Tidak dapat menerapkan perubahan tersebut",
