  "Nothing changes, and the Coach will remember you turned these down.": "Tidak ada yang berubah, dan Pelatih akan mengingat kamu menolaknya.",
  "Dismiss": "Tutup",
  "Based on your last {0} sessions": "Berdasarkan {0} sesi terakhirmu",
  "Your plan changed since the Coach looked at it. Suggestions that no longer match are greyed out. Ask for a fresh review to see them again.": "Rencanamu berubah sejak Pelatih melihatnya. Saran yang tidak lagi cocok akan berwarna abu-abu. Mintalah ulasan baru untuk melihatnya lagi.",
  "Doesn’t match your plan any more, so it can’t be applied.": "Tidak sesuai lagi dengan rencanamu, sehingga tidak dapat diterapkan.",
  "Apply nothing": "Tidak menerapkan apa pun",
