  "Connect to my server": "Hubungkan ke server saya",
  "Sync this device to your own self-hosted openGym instead.": "Sinkronkan perangkat ini ke openGym yang kamu hosting sendiri.",
  "Pair the mobile app": "Pasangkan aplikasi seluler",
  "Connect the openGym app on your phone to this account.": "Hubungkan aplikasi openGym di ponselmu ke akun ini.",
  "On the openGym app, choose “Connect to my server”, then enter this address and the code below. It expires in 5 minutes.": "Pada aplikasi openGym, pilih “Hubungkan ke server saya”, lalu masukkan alamat ini dan kode di bawah. Masa berlakunya habis dalam 5 menit.",
  "Enter your server address and the code": "Masukkan alamat servermu dan kodenya",
  "Connected": "Terhubung",
  "Could not connect": "Tidak dapat terhubung",
