  "Focus only on my routine “{0}”. Improve it: exercise choice, order, sets and reps, rep ranges, progression. Leave the other routines alone.": "Fokus hanya pada rutinitasku “{0}”. Optimalkan: variasi latihan, urutan gerakan, set dan repetisi, rentang rep, serta progresi beban. Jangan ubah rutinitas lainnya.",
