  "Your server can’t be reached. Your changes are saved on this device and sync once it answers again.": "Servermu tidak dapat dijangkau. Perubahanmu disimpan di perangkat ini dan disinkronkan setelah server merespons kembali.",
  "Your server can’t be reached. Showing the last copy synced with it.": "Servermu tidak dapat dijangkau. Menampilkan salinan terakhir yang disinkronkan dengan server.",
  "Server address unknown": "Alamat server tidak diketahui",
  "Pair again, or export a backup first. Going ahead anyway keeps a copy of these changes on this device until it connects to this server as this account again. Then they’re added back.": "Pasangkan lagi, atau ekspor cadangan terlebih dahulu. Tetap lanjutkan untuk menyimpan salinan perubahan ini di perangkat hingga terhubung kembali ke server dengan akun ini. Lalu perubahan tersebut akan disinkronkan kembali.",
  "Sign in again, or export a backup first. Going ahead anyway keeps a copy of these changes on this device until it connects to this server as this account again. Then they’re added back.": "Masuk lagi, atau ekspor cadangan terlebih dahulu. Tetap lanjutkan untuk menyimpan salinan perubahan ini di perangkat hingga terhubung kembali ke server dengan akun ini. Lalu perubahan tersebut akan disinkronkan kembali.",
