  "Show connection status": "Tampilkan status koneksi",
  "Off: the bar at the top is hidden. A dot on Home still warns when syncing is stuck.": "Nonaktif: bilah status di bagian atas disembunyikan. Titik indikator di Beranda tetap muncul jika sinkronisasi terkendala.",
  "Connection problem": "Masalah koneksi",
  "Backup folder": "Folder cadangan",
  "Chosen folder": "Folder yang dipilih",
