  "That took a little too long. Give it another go.": "Itu memakan waktu terlalu lama. Cobalah lagi.",
  "This server only takes changes made at {0}. If you opened openGym at another address, whoever runs the server can set ORIGIN and RP_ID to match it (the self-hosting guide shows how).": "Server ini hanya menerima perubahan yang dilakukan pada {0}. Jika kamu membuka openGym di alamat lain, siapa pun yang menjalankan server dapat mengatur ORIGIN dan RP_ID agar cocok (panduan hosting mandiri menunjukkan caranya).",
