  "Top of the range on all {0} sets. {1} {2} more, back to {3} sets of {4}.": "Batas repetisi atas tercapai di semua {0} set. Naikkan {1} {2}, kembali ke {3} set berisi {4} repetisi.",
  "Top of the range on all {0} sets. {1} {2} less help, back to {3} sets of {4}.": "Batas repetisi atas tercapai di semua {0} set. Kurangi bantuan {1} {2}, kembali ke {3} set berisi {4} repetisi.",
