  "Missed reps last time. Same sets and reps again ({0} of {1} to go).": "Repetisi yang terlewat terakhir kali. Set dan repetisi yang sama lagi ({0} dari {1} tersisa).",
  "Stuck for {0} sessions. Deload to {1} {2} and start again at {3} sets of {4}.": "Stagnan selama {0} sesi. Deload ke {1} {2} dan mulai lagi di {3} set berisi {4} repetisi.",
  "Stuck for {0} sessions. Back to {1} {2} of help, start again at {3} sets of {4}.": "Stagnan selama {0} sesi. Kembali ke bantuan {1} {2}, mulai lagi di {3} set berisi {4} repetisi.",
