  "Downloaded · {0}": "Diunduh · {0}",
  "Downloading… {0}%": "Mengunduh… {0}%",
  "No animation, just the picture. Easy on battery.": "Tanpa animasi, hanya gambar. Lebih hemat baterai.",
  "Not downloaded": "Tidak diunduh",
  "On this device": "Di perangkat ini",
  "Sharper animations aren’t available on this device yet. The built-in ones work everywhere.": "Animasi yang lebih tajam belum tersedia di perangkat ini. Yang bawaan berfungsi di mana saja.",
  "Sharper animations download once per figure. Until they’re here you see the built-in ones, so nothing ever goes blank.": "Animasi berkualitas lebih tinggi diunduh sekali per gerakan. Selama proses unduh berlangsung, kamu tetap melihat animasi bawaan agar tampilan tidak kosong.",
  "Still only": "Masih saja",
  "Waiting for Wi-Fi": "Menunggu Wi-Fi",
  "{0} px": "{0} px",
  "Make the box bigger": "Buat kotaknya lebih besar",
  "Make the box smaller": "Buat kotaknya lebih kecil",
  "Photo removed": "Foto dihapus",
  "A breather after one side, before the other. The full rest comes once both sides are done.": "Jeda napas sejenak sebelum lanjut ke sisi lainnya. Waktu istirahat penuh dimulai setelah kedua sisi selesai.",
  "Like the work sets": "Ikuti set utama",
  "No timer": "Tanpa timer",
  "Pick a time": "Pilih waktu",
  "Rest between sides": "Istirahat di antara sisi",
  "Rest between warm-ups": "Istirahat di antara pemanasan",
  "Warm-ups are light, so they can rest less, or not at all. The last one still gets the full rest before your first work set.": "Set pemanasan berbeban ringan, sehingga waktu istirahat bisa lebih singkat atau ditiadakan. Set pemanasan terakhir tetap mendapat istirahat penuh sebelum set utama dimulai.",
  "Add photos": "Tambahkan foto",
  "Each photo goes on the day it was taken.": "Setiap foto berlangsung pada hari pengambilannya.",
  "No progress photos yet. Add one for today or any day before.": "Belum ada foto progres. Tambahkan satu untuk hari ini atau hari sebelumnya.",
  "The photo says it was taken on {0}. Change the day if it was another one.": "Foto ini diambil pada {0}. Ubah tanggal jika foto ini diambil pada hari yang berbeda.",
  "They all go on the day below.": "Semuanya akan dijadwalkan pada hari di bawah ini.",
  "Which day is this photo from?": "Foto ini diambil dari hari apa?",
  "Your server keeps photos only on days with a workout. An update lets it keep them for any day.": "Servermu hanya menyimpan foto pada hari-hari yang memiliki sesi latihan. Pembaruan server memungkinkannya menyimpan foto untuk hari apa pun.",
  "Add {0} photo": "Tambahkan {0} foto",
  "Add {0} photos": "Tambahkan {0} foto",
  "{0} photo added": "{0} foto ditambahkan",
  "{0} photos added": "{0} foto ditambahkan",
  "{0} photo knows its day and goes there. The others go on the day below.": "{0} foto cocok dengan tanggal pengambilannya dan ditempatkan di sana. Foto lainnya dimasukkan ke tanggal di bawah.",
  "{0} photos know their day and go there. The others go on the day below.": "{0} foto cocok dengan tanggal pengambilannya dan ditempatkan di sana. Foto lainnya dimasukkan ke tanggal di bawah.",
  "Every progress photo, lined up by date, for any day. Plus a before/after slider.": "Setiap foto progres, diurutkan berdasarkan tanggal, untuk hari apa pun. Ditambah penggeser sebelum/sesudah.",
  "Add a backup": "Tambah latihan cadangan",
  "Backups": "Latihan cadangan",
  "Backups for {0}": "Latihan cadangan untuk {0}",
  "Everything else": "Segala sesuatu yang lain",
  "Machine taken? Pick what you’d do instead, and a swap mid-workout offers these first.": "Mesin sedang dipakai orang? Pilih variasi penggantinya, dan opsi ganti di tengah sesi akan mengutamakan pilihan ini.",
  "Remove “{0}”": "Hapus “{0}”",
  "That’s plenty of backups.": "Latihan cadangan sudah cukup banyak.",
  "Your backups": "Latihan cadanganmu",
  "Swap to {0}": "Tukar ke {0}",
  "Planned backup, same sets and reps": "Latihan cadangan terencana, set dan repetisi serupa",
  "Nothing to add in weight here: it goes up in reps, then sets.": "Tidak ada yang menambah beban di sini: naik dalam repetisi, lalu set.",
  "In Cards and Focus, Prev and Next hop over a finished exercise.": "Di Kartu dan Fokus, Sebelumnya dan Berikutnya melewati latihan yang sudah selesai.",
  "Skip completed exercises": "Lewati latihan yang sudah selesai",
  "This app can’t confirm with a passkey. Make the code in a browser signed in to this profile, or add a password there first.": "Aplikasi ini tidak dapat mengonfirmasi dengan kunci sandi. Buat kode di browser untuk masuk ke profil ini, atau tambahkan kata sandi di sana terlebih dahulu.",
  "Apple Watch": "Apple Watch",
  "Weight": "Beban",
  "Send workouts to the watch": "Kirim latihan ke jam tangan",
  "Open on the watch": "Buka di jam tangan",
  "Start a workout on the phone and openGym pops up on your wrist.": "Mulai latihan di ponsel dan openGym muncul di pergelangan tanganmu.",
  "Not allowed": "Tidak diizinkan",
  "Turn on Apple Health and the watch measures your heart rate for every set.": "Nyalakan Apple Health dan jam tangan akan mengukur detak jantung kamu untuk setiap set.",
  "Tap the wrist when a rest is over": "Ketuk pergelangan tangan saat istirahat selesai",
  "No Apple Watch paired with this iPhone": "Tidak ada Apple Watch yang dipasangkan dengan iPhone ini",
  "openGym is not on your Apple Watch yet. Install it in the Watch app.": "openGym belum terpasang di Apple Watch kamu. Instal melalui aplikasi Apple Watch di iPhone.",
  "openGym is on your Apple Watch": "openGym ada di Apple Watch kamu",
  "Last heard from the watch: {0}": "Terakhir terdengar dari jam tangan: {0}",
  "The watch hasn’t checked in yet. Open openGym on it once.": "Smartwatch belum terhubung. Buka openGym di jam tanganmu sekali.",
  "Not allowed on the watch. Allow it in the Health app on your iPhone.": "Tidak diizinkan di jam tangan. Izinkan di aplikasi Kesehatan di iPhone kamu.",
  "Heart rate during the workout and next to each set, and the workout saved to Apple Health. The watch asks once.": "Detak jantung selama latihan dan di setiap set, serta sesi latihan tersimpan ke Apple Health. Apple Watch akan meminta izin sekali.",
  "Apple Health": "Apple Health",
  "Write to Apple Health": "Menulis ke Apple Health",
  "Open Apple Health": "Buka Kesehatan Apple",
  "Workouts and weigh-ins go to Apple Health when you finish or change them.": "Sesi latihan dan catatan berat badan akan disinkronkan ke Apple Health saat kamu menyelesaikan atau mengubahnya.",
  "Writing to Apple Health": "Menulis ke Apple Health",
  "Apple Health permission not granted": "Izin Apple Health tidak diberikan",
  "Could not write to Apple Health": "Tidak dapat menulis ke Apple Health",
  "Could not remove it from Apple Health": "Tidak dapat menghapusnya dari Apple Health",
  "Stop writing to Apple Health?": "Berhenti menulis ke Apple Health?",
  "What openGym already wrote can stay in Apple Health as your data, or be removed from it.": "Apa yang telah ditulis oleh openGym dapat tetap ada di Apple Health sebagai datamu, atau dihapus darinya.",
  "Your workouts in Apple Health": "Latihanmu di Apple Health",
  "openGym can save every workout and weigh-in to Apple Health, and your Apple Watch can show your heart rate while you lift.": "openGym dapat menyimpan setiap sesi latihan dan catatan berat badan ke Apple Health, dan Apple Watch dapat menampilkan detak jantungmu saat mengangkat beban.",
  "Workouts and weigh-ins saved to Apple Health": "Latihan dan penimbangan disimpan ke Apple Health",
  "Heart rate per set on your Apple Watch": "Detak jantung per set di Apple Watch kamu",
  "AirPods Pro 3 or Powerbeats Pro 2 in? Your iPhone measures the heart rate for every set, unless your Apple Watch is already on it.": "Memakai AirPods Pro 3 atau Powerbeats Pro 2? iPhone-mu mengukur detak jantung untuk setiap set, kecuali jika sudah diukur oleh Apple Watch.",
  "Switch it off anytime in Settings": "Nonaktifkan kapan saja di Pengaturan",
  "You can change it anytime in Settings.": "Kamu dapat mengubahnya kapan saja di Pengaturan.",
