  "Not trained:": "Belum dilatih:",
  "Rounded to whole sets. A set counts fully for its main muscle and partly for the ones that help, so the muscles add up to more than your work sets.": "Dibulatkan ke set utuh. Satu set dihitung penuh untuk otot utama dan sebagian untuk otot pendukung, sehingga total per otot bisa melebihi jumlah set utama.",
