  "Each adds its own routines, so your plan stays as it is until you start it.": "Masing-masing menambahkan rutinitasnya sendiri, sehingga rencanamu tetap seperti semula sampai kamu memulainya.",
  "Effort for the week": "Tingkat usaha minggu ini",
  "Empty leaves the weight to your progression. A %1RM is worked out from your best estimated 1RM.": "Jika kosong, beban ditentukan oleh progresimu. %1RM dihitung dari estimasi 1RM terbaikmu.",
  "End programme": "Akhiri program",
  "End “{0}”?": "Akhiri “{0}”?",
  "Four days. Your progression picks the weights, the effort climbs to RPE 9, then a deload.": "Empat hari. Progresimu menentukan beban, tingkat usaha naik hingga RPE 9, lalu deload.",
  "Heavier means every %1RM goes up {0} points.": "Lebih berat berarti setiap %1RM naik {0} poin.",
  "It is running: ending it brings your plan back. Its routines stay.": "Program sedang berjalan: mengakhirinya akan memulihkan rencanamu. Rutinitasnya tetap tersimpan.",
  "Its routines stay.": "Rutinitasnya tetap tersimpan.",
  "Its schedule takes over your plan until you end it. Then your plan comes back as it was.": "Jadwalnya menggantikan rencanamu sampai kamu mengakhirinya. Setelah itu, rencanamu kembali seperti semula.",
  "Lighter weights, and its sessions do not count toward progression.": "Beban lebih ringan, dan sesinya tidak dihitung dalam progresi.",
  "Linear 5×5 style, 12 weeks": "Gaya linier 5×5, 12 minggu",
