  "This lives in the openGym phone app.": "Fitur ini ada di aplikasi ponsel openGym.",
  "Your watch or scale writes here too? Garmin, COROS, Fitbit, Withings, Oura and friends reach openGym this way.": "Jam tangan atau timbanganmu juga menulis data ke sini? Garmin, COROS, Fitbit, Withings, Oura, dan sejenisnya terhubung ke openGym melalui cara ini.",
