  "Only the warm-ups you plan yourself.": "Hanya pemanasan yang kamu rencanakan sendiri.",
  "Ramped from the work weight: more rungs when it is heavy, fewer when it is light.": "Ditingkatkan bertahap dari beban set utama: lebih banyak tahapan saat berat, lebih sedikit saat ringan.",
