  "Routines, exercises, sets and reps, warm-ups, programmes, your weekly schedule, progression settings and what your gym can load.": "Rutinitas, latihan, set dan repetisi, pemanasan, program, jadwal mingguanmu, pengaturan progresi, serta beban yang tersedia di gym-mu.",
  "Running on empty": "Kehabisan tenaga",
  "Saved in the routine, scaled to your work weight": "Tersimpan dalam rutinitas, disesuaikan dengan beban set utamamu",
