  "Something else": "Hal lain",
  "Squats, presses, rows and friends get a ramp. Curls and raises start cold.": "Squat, press, row, dan sejenisnya mendapat set bertahap. Curl dan raise langsung dimulai tanpa pemanasan.",
  "Straight into the work sets.": "Langsung ke set utama.",
  "That workout is over, so these can’t be applied any more.": "Latihan tersebut sudah selesai, jadi perubahan ini tidak bisa lagi diterapkan.",
  "The app ramps up from your work weight: more warm-up sets when it is heavy, fewer when it is light, on your gym’s plates.": "Aplikasi meningkatkan beban bertahap dari beban set utamamu: lebih banyak set pemanasan saat berat, lebih sedikit saat ringan, dengan plat di gym-mu.",
  "The rack is taken, so do it at the end. The rest of the session does not need it.": "Rack sedang dipakai, jadi lakukan di akhir sesi. Sisa sesi latihan tidak membutuhkannya.",
  "There’s no workout running.": "Tidak ada latihan yang sedang berjalan.",
  "These warm-ups come before the work sets every session, as a share of the work weight, so they grow with it.": "Pemanasan ini dilakukan sebelum set utama di setiap sesi, sebagai persentase dari beban set utama, sehingga otomatis bertambah seiring peningkatan beban.",
  "This is the demo, so there is no AI model behind me. On your own server I read your session and suggest changes like these.": "Ini adalah demo, jadi tidak ada model AI di balik Pelatih. Di server milikmu sendiri, Pelatih membaca sesimu dan menyarankan perubahan seperti ini.",
