  'Added before your work sets and left out of volume, records and progression. On an assistance machine each one has more help than the work set, stepping down toward it, and you can still change any of them mid-session.': 'Ditambahkan sebelum set utama dan tidak dihitung dalam volume, rekor, dan progresi. Di mesin assisted, tiap set mendapat bantuan lebih besar daripada set utama dan berkurang bertahap mendekatinya, dan kamu tetap bisa mengubahnya di tengah sesi.',
  'The Coach hit its AI provider’s limit. Try again later, or the instance owner needs to check the plan or key.': 'Pelatih AI mencapai batas kuota penyedia AI-nya. Coba lagi nanti, atau pemilik server perlu memeriksa paket langganan atau API key.',
