  'Added before your work sets. They count in your volume (Settings), but stay out of records and progression. On an assistance machine each one has more help than the work set, stepping down toward it, and you can still change any of them mid-session.': 'Ditambahkan sebelum set utama. Dihitung dalam volume (Pengaturan), tapi tidak masuk rekor dan progresi. Di mesin bantuan, tiap set mendapat bantuan lebih besar daripada set utama dan berkurang bertahap mendekatinya, dan kamu tetap bisa mengubahnya di tengah sesi.',
